package cl.bolsillo.app;
import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
final class BankTemplates {
 static void show(MainActivity a,boolean first,Runnable done){a.attempt(()->{Forms.Form f=new Forms.Form(a,first?"Tus bancos, a tu manera":"Añadir bancos");f.note("Elige los que usas. Las cuentas se guardan aquí; después puedes ajustar sus saldos.");EditText search=f.field("Buscar banco","",false);Set<String> current=new HashSet<>();JSONArray accounts=LocalData.read(a).getJSONArray("accounts");for(int i=0;i<accounts.length();i++){JSONObject account=accounts.getJSONObject(i);if(!account.optBoolean("archived")&&account.optString("type").equals("bank"))current.add(account.optString("institution"));}LinkedHashMap<CheckBox,String> choices=new LinkedHashMap<>();List<View> rows=new ArrayList<>();for(String[] bank:BankCatalog.BANKS){LinearLayout row=Modern.row(a);row.setBackground(Glass.material(a,215,20,Glass.BLUE));CheckBox check=new CheckBox(a);Controls.style(check);check.setText(bank[1]+(current.contains(bank[0])?" · Añadido":""));check.setTypeface(Glass.font(a,500));check.setMinHeight(a.dp(60));check.setChecked(current.contains(bank[0]));check.setEnabled(!current.contains(bank[0]));row.addView(check,new LinearLayout.LayoutParams(0,-2,1));row.addView(Icons.badge(a,bank[0],32),new LinearLayout.LayoutParams(a.dp(32),a.dp(32)));row.setPadding(a.dp(6),a.dp(2),a.dp(10),a.dp(2));row.setTag(bank[1]);Modern.add(f.box,row,6);choices.put(check,bank[0]);rows.add(row);}search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence text,int start,int count,int after){}public void onTextChanged(CharSequence text,int start,int before,int count){String q=BankNotificationParser.normalize(text.toString());for(View row:rows)row.setVisibility(BankNotificationParser.normalize(row.getTag().toString()).contains(q)?View.VISIBLE:View.GONE);}public void afterTextChanged(android.text.Editable text){}});f.action("Otra cuenta o institución",()->{f.dialog.dismiss();a.attempt(()->Forms.account(a,null));});Runnable save=()->a.attempt(()->{List<String> selected=new ArrayList<>();for(Map.Entry<CheckBox,String> entry:choices.entrySet())if(entry.getKey().isChecked()&&!current.contains(entry.getValue()))selected.add(entry.getValue());LocalData.change(a,d->BankCatalog.add(d,selected));Set<String> added=new HashSet<>();JSONArray after=LocalData.read(a).getJSONArray("accounts");for(int i=0;i<after.length();i++){JSONObject account=after.getJSONObject(i);if(selected.contains(account.optString("institution"))&&!account.optBoolean("archived")&&account.optString("type").equals("bank"))added.add(account.getString("id"));}PaymentCards.addDefaults(a,added);f.dialog.dismiss();a.data=LocalData.read(a);if(done!=null)done.run();else a.render();});if(f.dialog instanceof SheetDialog)((SheetDialog)f.dialog).actions(first?"Continuar":"Añadir seleccionados",save);else f.action("Añadir seleccionados",save::run);if(first)f.action("Ahora no",()->{f.dialog.dismiss();a.attempt(()->{LocalData.change(a,d->d.put("bankSetupPending",false));if(done!=null)done.run();});});});}
}
